     1→/**
     2→ * Integration tests for authentication routes and RBAC middleware.
     3→ *
     4→ * Uses Fastify's inject() method to make real HTTP requests through the full
     5→ * request lifecycle (validation → route handler → response) against a real
     6→ * PostgreSQL test database.
     7→ *
     8→ * Coverage:
     9→ *   POST /auth/login     — happy path, validation, lockout, audit logs
    10→ *   POST /auth/logout    — token invalidation, idempotency
    11→ *   GET  /auth/me        — session validation, phone masking, field safety
    12→ *   requireAuth          — protected route gating
    13→ *   requireRole          — RBAC enforcement per role
    14→ */
    15→
    16→import {
    17→  describe,
    18→  it,
    19→  expect,
    20→  beforeAll,
    21→  beforeEach,
    22→  afterAll,
    23→} from 'vitest';
    24→import type { FastifyInstance } from 'fastify';
    25→import { eq, sql } from 'drizzle-orm';
    26→
    27→import { buildAuthTestApp } from '../test/app.js';
    28→import {
    29→  testDb,
    30→  runMigrations,
    31→  clearAllTables,
    32→  closeDb,
    33→} from '../test/db.js';
    34→import { seedUser } from '../test/helpers.js';
    35→import { users } from '../db/schema/users.js';
    36→import { sessions } from '../db/schema/sessions.js';
    37→import { auditLogs } from '../db/schema/audit-logs.js';
    38→
    39→// ── Shared state ───────────────────────────────────────────────────────────────
    40→
    41→let app: FastifyInstance;
    42→
    43→beforeAll(async () => {
    44→  // Run migrations once — idempotent; safe to call if DB already has tables.
    45→  await runMigrations();
    46→
    47→  // Build the test app with a protected test route for RBAC checks.
    48→  app = await buildAuthTestApp(async (fastify) => {
    49→    // Route accessible to any authenticated user (requireAuth only)
    50→    fastify.get(
    51→      '/test/protected',
    52→      { preHandler: [fastify.requireAuth] },
    53→      async (req) => ({ ok: true, role: req.user!.role }),
    54→    );
    55→
    56→    // Route requiring manager or admin
    57→    fastify.get(
    58→      '/test/manager-only',
    59→      {
    60→        preHandler: [
    61→          fastify.requireAuth,
    62→          fastify.requireRole('manager', 'admin'),
    63→        ],
    64→      },
    65→      async () => ({ ok: true }),
    66→    );
    67→
    68→    // Route requiring admin only
    69→    fastify.get(
    70→      '/test/admin-only',
    71→      {
    72→        preHandler: [
    73→          fastify.requireAuth,
    74→          fastify.requireRole('admin'),
    75→        ],
    76→      },
    77→      async () => ({ ok: true }),
    78→    );
    79→  });
    80→});
    81→
    82→beforeEach(async () => {
    83→  await clearAllTables();
    84→});
    85→
    86→afterAll(async () => {
    87→  await app.close();
    88→  await closeDb();
    89→});
