    91→// ── Helpers ────────────────────────────────────────────────────────────────────
    92→
    93→/** POST /auth/login and return the parsed response. */
    94→async function login(username: string, password: string) {
    95→  return app.inject({
    96→    method: 'POST',
    97→    url: '/auth/login',
    98→    headers: { 'content-type': 'application/json' },
    99→    body: JSON.stringify({ username, password }),
   100→  });
   101→}
   102→
   103→/** GET /auth/me with a bearer token. */
   104→async function me(token: string) {
   105→  return app.inject({
   106→    method: 'GET',
   107→    url: '/auth/me',
   108→    headers: { authorization: `Bearer ${token}` },
   109→  });
   110→}
   111→
   112→/** POST /auth/logout with a bearer token. */
   113→async function logout(token: string) {
   114→  return app.inject({
   115→    method: 'POST',
   116→    url: '/auth/logout',
   117→    headers: { authorization: `Bearer ${token}` },
   118→  });
   119→}
   120→
   121→/** Force a user into a locked state by setting lockedUntil far in the future. */
   122→async function lockUser(userId: string) {
   123→  await testDb
   124→    .update(users)
   125→    .set({
   126→      failedAttempts: 5,
   127→      lockedUntil: new Date(Date.now() + 15 * 60 * 1000),
   128→      updatedAt: sql`now()`,
   129→    })
   130→    .where(eq(users.id, userId));
   131→}
   132→
   133→/** Force a lockout that has already expired. */
   134→async function expireLockout(userId: string) {
   135→  await testDb
   136→    .update(users)
   137→    .set({
   138→      failedAttempts: 5,
   139→      lockedUntil: new Date(Date.now() - 1000), // 1 second in the past
   140→      updatedAt: sql`now()`,
   141→    })
   142→    .where(eq(users.id, userId));
   143→}
