   149→describe('POST /auth/login — happy path', () => {
   150→  it('returns 200 with token, expiresAt, and user object on valid credentials', async () => {
   151→    await seedUser({ username: 'alice', password: 'password1234', role: 'customer' });
   152→
   153→    const res = await login('alice', 'password1234');
   154→
   155→    expect(res.statusCode).toBe(200);
   156→    const body = res.json<{ token: string; expiresAt: string; user: Record<string, unknown> }>();
   157→    expect(typeof body.token).toBe('string');
   158→    expect(body.token).toHaveLength(64); // randomBytes(32).toString('hex') = 64 chars
   159→    expect(typeof body.expiresAt).toBe('string');
   160→    expect(() => new Date(body.expiresAt)).not.toThrow();
   161→  });
   162→
   163→  it('expiresAt is approximately 8 hours from now', async () => {
   164→    await seedUser({ username: 'alice', password: 'password1234' });
