   169→    const { expiresAt } = res.json<{ expiresAt: string }>();
   170→    const exp = new Date(expiresAt).getTime();
   171→    const eightHours = 8 * 60 * 60 * 1000;
   172→
   173→    expect(exp).toBeGreaterThanOrEqual(before + eightHours - 1000);
   174→    expect(exp).toBeLessThanOrEqual(after + eightHours + 1000);
   175→  });
   176→
   177→  it('user object contains id, username, role', async () => {
   178→    const seeded = await seedUser({ username: 'alice', password: 'password1234', role: 'associate' });
   179→    const body = (await login('alice', 'password1234')).json<{ user: Record<string, unknown> }>();
   180→
