   133→/** Force a lockout that has already expired. */
   134→async function expireLockout(userId: string) {
   135→  await testDb
   136→    .update(users)
   137→    .set({
   138→      failedAttempts: 5,
   139→      lockedUntil: new Date(Date.now() - 1000), // 1 second in the past
   140→      updatedAt: sql`now()`,
   141→    })
   142→    .where(eq(users.id, userId));
   143→}
