    43→beforeAll(async () => {
    44→  // Run migrations once — idempotent; safe to call if DB already has tables.
    45→  await runMigrations();
    46→
    47→  // Build the test app with a protected test route for RBAC checks.
    48→  app = await buildAuthTestApp(async (fastify) => {
    49→    // Route accessible to any authenticated user (requireAuth only)
