    27→/** Log in and return an Authorization header value (e.g. "Bearer abc123"). */
    28→async function loginAs(
    29→  app: FastifyInstance,
    30→  username: string,
    31→  password = 'password1234',
    32→): Promise<string> {
    33→  const res = await app.inject({
    34→    method: 'POST',
    35→    url: '/auth/login',
    36→    payload: { username, password },
    37→  });
    38→  expect(res.statusCode).toBe(200);
    39→  const token = res.json().token as string;
