     1→/**
     2→ * Integration tests for product catalog endpoints.
     3→ *
     4→ * Covers:
     5→ *   GET /products        — list, pagination, filters, sorting, full-text search
     6→ *   GET /products/:id    — single product by UUID
     7→ *
     8→ * All tests use Fastify's inject() against a real PostgreSQL test database
     9→ * so that the tsvector generated column, GIN index, and price ordering work
    10→ * exactly as they do in production.
    11→ */
    12→
    13→import {
    14→  describe,
    15→  it,
    16→  expect,
    17→  beforeAll,
    18→  beforeEach,
    19→  afterAll,
    20→} from 'vitest';
    21→import type { FastifyInstance } from 'fastify';
    22→
    23→import { buildProductTestApp } from '../test/app.js';
    24→import { runMigrations, clearAllTables, closeDb } from '../test/db.js';
    25→import { seedProduct } from '../test/helpers.js';
    26→
    27→// ── Shared app + lifecycle ─────────────────────────────────────────────────────
    28→
    29→let app: FastifyInstance;
    30→
    31→beforeAll(async () => {
    32→  await runMigrations();
    33→  app = await buildProductTestApp();
    34→});
    35→
    36→beforeEach(async () => {
    37→  await clearAllTables();
    38→});
    39→
    40→afterAll(async () => {
    41→  await app.close();
    42→  await closeDb();
