    45→// ── Helpers ────────────────────────────────────────────────────────────────────
    46→
    47→type ProductItem = {
    48→  id: string;
    49→  name: string;
    50→  description: string | null;
    51→  brand: string | null;
    52→  price: string;
    53→  stockQty: number;
    54→  category: string | null;
    55→  isActive: boolean;
    56→  createdAt: string;
    57→};
    58→
    59→type ListResponse = {
    60→  data: ProductItem[];
    61→  total: number;
    62→  limit: number;
    63→  offset: number;
    64→};
    65→
    66→async function getProducts(query: Record<string, string | number | boolean> = {}) {
    67→  const qs = new URLSearchParams(
    68→    Object.entries(query).map(([k, v]) => [k, String(v)]),
    69→  ).toString();
    70→  return app.inject({
    71→    method: 'GET',
    72→    url: qs ? `/products?${qs}` : '/products',
    73→  });
    74→}
    75→
    76→async function getProduct(id: string) {
    77→  return app.inject({ method: 'GET', url: `/products/${id}` });
    78→}
