// ── Test helpers ──────────────────────────────────────────────────────────────

/** Log in and return an Authorization header value (e.g. "Bearer abc123"). */
async function loginAs(
  username: string,
  password = 'password1234',
): Promise<string> {
  const res = await inject(url, {
    method: 'POST',
    url: '/auth/login',
    payload: { username, password },
  });
  expect(res.statusCode).toBe(200);
  const token = res.json().token as string;
  expect(token).toBeDefined();
  return `Bearer ${token}`;
}

async function createCart(auth: string) {
  return inject(url, {
    method: 'POST',
    url: '/cart',
    headers: auth ? { authorization: auth } : {},
  });
}

async function getCart(auth: string) {
  return inject(url, {
    method: 'GET',
    url: '/cart',
    headers: auth ? { authorization: auth } : {},
  });
}

async function addItem(
  auth: string,
  productId: string,
  qty: number,
) {
  return inject(url, {
    method: 'POST',
    url: '/cart/items',
    headers: auth ? { authorization: auth } : {},
    payload: { productId, qty },
  });
}

async function updateItem(
  auth: string,
  itemId: string,
  qty: number,
) {
  return inject(url, {
    method: 'PUT',
    url: `/cart/items/${itemId}`,
    headers: auth ? { authorization: auth } : {},
    payload: { qty },
  });
}

async function deleteItem(auth: string, itemId: string) {
  return inject(url, {
    method: 'DELETE',
    url: `/cart/items/${itemId}`,
    headers: auth ? { authorization: auth } : {},
  });
}

/** Force a cart's expiresAt into the past directly via the DB. */
async function expireCart(cartId: string) {
  const past = new Date(Date.now() - 1000);
  await testDb
    .update(carts)
    .set({ expiresAt: past })
    .where(eq(carts.id, cartId));
}

